// The quote contract as shipped (schema/quote.schema.json, generated by the checkout): line codes
// base/fuel/remote/oversize, no negative amounts, and vouchers never appear in a shipping quote.
import { test } from "node:test";
import assert from "node:assert/strict";
import { main } from "../src/cli.ts";
import { quote, type QuoteRequest } from "../src/quote.ts";

const CODES = ["base", "fuel", "remote", "oversize"];
const FIELDS = ["country", "postcode", "zone", "billableKg", "lines", "totalCents", "currency", "transitDays", "deliveryDate"];
const box = (weightKg: number, lengthCm: number, widthCm: number, heightCm: number) => ({ weightKg, lengthCm, widthCm, heightCm });
const small = box(2.3, 20, 15, 10);

/** The shipped schema's rules, restated here (the copy in the repository is the checkout's). */
function conforms(value: unknown): void {
  const q = JSON.parse(JSON.stringify(value));
  for (const key of Object.keys(q)) {
    assert.ok(FIELDS.includes(key), `unexpected field ${key}`);
  }
  assert.ok(["DE", "AT"].includes(q.country));
  assert.ok(Number.isInteger(q.zone) && q.zone >= 1 && q.zone <= 4);
  assert.equal((q.billableKg * 2) % 1, 0);
  assert.equal(q.currency, "EUR");
  assert.ok(Array.isArray(q.lines) && q.lines.length >= 2);
  for (const charge of q.lines) {
    assert.deepEqual(Object.keys(charge).sort(), ["amountCents", "code", "label"]);
    assert.ok(CODES.includes(charge.code), `line code ${charge.code}`);
    assert.ok(Number.isInteger(charge.amountCents) && charge.amountCents >= 0, `${charge.code} ${charge.amountCents}`);
    assert.ok(typeof charge.label === "string" && charge.label.length > 0);
  }
  assert.ok(Number.isInteger(q.totalCents) && q.totalCents >= 0);
  assert.equal(q.totalCents, q.lines.reduce((sum: number, charge: { amountCents: number }) => sum + charge.amountCents, 0));
}

test("a voucher never shows up in a shipping quote", () => {
  for (const voucherCents of [300, 749, 5000]) {
    const request = { country: "DE", postcode: "10115", parcel: small, voucherCents } as QuoteRequest;
    let q;
    try {
      q = quote(request);
    } catch {
      continue; // refusing a voucher is fine: the checkout applies vouchers, not shipquote
    }
    conforms(q);
    assert.deepEqual(q, quote({ country: "DE", postcode: "10115", parcel: small }));
  }
});

test("every quote matches the shipped schema", () => {
  const requests: QuoteRequest[] = [
    { country: "DE", postcode: "01067", parcel: small },
    { country: "DE", postcode: "09484", parcel: small },
    { country: "DE", postcode: "25980", parcel: box(12, 60, 40, 40), shipDate: "2026-12-23" },
    { country: "DE", postcode: "50667", parcel: box(18, 50, 40, 30) },
    { country: "DE", postcode: "80331", parcel: box(9, 130, 30, 20) },
    { country: "AT", postcode: "1010", parcel: box(4.2, 30, 30, 30), shipDate: "2026-11-05" },
    { country: "AT", postcode: "6764", parcel: box(0.2, 10, 10, 5) },
  ];
  for (const request of requests) {
    conforms(quote(request));
  }
});

test("quote --json output matches the shipped schema", () => {
  let stdout = "";
  const status = main(["quote", "--postcode", "18565", "--weight", "1", "--dims", "20x15x10", "--ship-date", "2026-11-05", "--json"], {
    stdout: { write: (text: string) => (stdout += text) },
    stderr: { write: () => true },
  });
  assert.equal(status, 0);
  conforms(JSON.parse(stdout));
});

test("ordinary quotes are unchanged", () => {
  assert.equal(quote({ country: "DE", postcode: "10115", parcel: small }).totalCents, 749);
  assert.equal(quote({ country: "DE", postcode: "09484", parcel: small }).totalCents, 1199);
  assert.equal(quote({ country: "AT", postcode: "1010", parcel: box(4.2, 30, 30, 30) }).totalCents, 2160);
  assert.equal(quote({ country: "DE", postcode: "80331", parcel: box(9, 130, 30, 20) }).totalCents, 2817);
});
